#include <iostream>

int main() {
    int players = 4;
    float score = 98.5f;       // 'f' tells C++ it's a float
    double pi = 3.1415926535; // Default is double
    char grade = 'A';          // Single quotes for single char
    bool isGameOver = false;

    std::cout << "Players: " << players << std::endl;
    std::cout << "Score: " << score << std::endl;
    std::cout << "Pi: " << pi << std::endl;
    std::cout << "Grade: " << grade << std::endl;
    std::cout << "Game Over: " << isGameOver << std::endl; // Prints 0
    return 0;
}
